python
def insertionTabsTotalReceipt(drawers):
    a=drawers
    out=[]
    for x in a[1]:
        left,right=0,len(a[0])
        while left<right:
            mid=(left+right)//2
            if a[0][mid]<x: left=mid+1
            else: right=mid
        out.append(left)
    return sum(out)


java
class Solution {
  public int insertionTabsTotalReceipt(int[][] drawers) {
    int[][] a=drawers; List<Integer> out=new ArrayList<>();
    {for(int x:a[1]){int l=0,r=a[0].length;while(l<r){int m=(l+r)/2;if(a[0][m]<x)l=m+1;else r=m;}out.add(l);}}
    int answer=0;for(int x:out)answer+=x;return answer;
  }
}
